window.AUTH=window.AUTH||{};window.AUTH["21-1326"]={"d":"21-1326","id":"2022/21-1326","n":"U.S. ex rel. Schutte v. SuperValu Inc.","briefs":[{"k":"petitioner","label":"Brief of petitioners United States ex rel. Tracy Schutte, et al.","date":"2023-02-17","url":"https://www.supremecourt.gov/DocketPDF/21/21-1326/255049/20230217125159663_21-1326%20and%2022-111%20ts.pdf","side":"pet","n":47},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2023-02-24","url":"https://www.supremecourt.gov/DocketPDF/21/21-1326/255556/20230224151138222_21-1326tsacUnitedStates.pdf","side":"us","n":44},{"k":"respondent","label":"Brief of respondents SuperValu, Inc., et al. and Safeway, Inc.","date":"2023-03-21","url":"https://www.supremecourt.gov/DocketPDF/21/21-1326/259547/20230321152707264_Schutte%20Proctor%20-%20Respondents%20Brief%20-%20FINAL.pdf","side":"res","n":61},{"k":"reply","label":"Reply of petitioners United States ex rel. Tracy Schutte, et al.","date":"2023-04-07","url":"https://www.supremecourt.gov/DocketPDF/21/21-1326/263051/20230407134214922_21-1326%20and%2022-111%20reply.pdf","side":"pet","n":25}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us2r30_g2bh.pdf","tr":true,"items":[{"t":"case","label":"Air & Liquid Sys. Corp. v. DeVries","cite":"139 S. Ct. 986","y":2019,"id":"2018/17-1104","sc":1,"sum":"In the maritime tort context, a product manufacturer has a duty to warn when its product requires incorporation of a part, the manufacturer knows or has reason to know that the integrated product is likely to be dangerous for its intended uses, and the manufacturer has no reason to believe that the product’s users will realize that danger.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25"}},{"t":"case","label":"Cedar Point Nursery v. Hassid","cite":"141 S. Ct. 2063","y":2021,"id":"2020/20-107","sc":1,"sum":"A California regulation granting labor organizations a “right to take access” to an agricultural employer’s property to solicit support for unionization constitutes a per se physical taking.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25"}},{"t":"case","label":"Com. Contractors, Inc. v. United States","cite":"154 F.3d 1357","y":1998,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/154/1357/","by":{"0":"37"}},{"t":"case","label":"Cooper v. Schlesinger","cite":"111 U.S. 148","y":1884,"id":"scdb/1883-204","sc":1,"sum":"Damages — Fraudulent Representations — Trial.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"29, 30","2":"37"}},{"t":"case","label":"Derry v. Peek","cite":"14 A.C. 337","y":1889,"url":"https://www.courtlistener.com/c/A.C./14/337/","op":2,"by":{"0":"25, 26"}},{"t":"case","label":"Farmer v. Brennan","cite":"511 U.S. 825","y":1994,"id":"1993/92-7247","sc":1,"op":2,"sum":"The Supreme Court held that prison officials may be liable if they showed “deliberate indifference” to a substantial risk of serious harm when the official was subjectively aware of the risk and disregarded it. The Court remanded the case for further consideration of whether prison officials were aware of the risk to Farmer.","sumSrc":"Oyez","by":{"0":"41, 55","1":"18, 23"}},{"t":"case","label":"Global-Tech Appliances, Inc. v. SEB S.A.","cite":"563 U.S. 754","y":2011,"id":"2010/10-6","sc":1,"op":1,"sum":"The Court ruled that induced infringement under the patent clause requires knowledge that the induced acts constitute patent infringement.","sumSrc":"Oyez","by":{"0":"35","1":"17","2":"25"}},{"t":"case","label":"Halo Elecs., Inc. v. Pulse Elecs., Inc.","cite":"579 U.S. 93","y":2016,"id":"2015/14-1513","sc":1,"op":6,"ar":6,"sum":"The Court determined that the rigid two-part test is not necessary for determining whether a patentee is eligible for enhanced damages under 35 U.S.C §284.","sumSrc":"Oyez","by":{"0":"41, 47","1":"14, 19, 26-30","2":"42, 43","3":"8, 9, 12"}},{"t":"case","label":"Heckler v. Cmty. Health Servs. of Crawford Cnty., Inc.","cite":"467 U.S. 51","y":1984,"id":"1983/83-56","sc":1,"sum":"Under the Medicare program, providers of health care services are reimbursed for the reasonable cost of services rendered to Medicare beneficiaries and are required to submit annual cost reports which are audited to determine actual costs. The Secretary of Health and Human Services (Secretary) may reopen any reimbursement determination within a 3-year period and make appropriate adjustments. Respondent nonprofit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44, 45","1":"13, 25, 31","2":"32, 51, 56","3":"11, 20"}},{"t":"case","label":"Howard v. Gould","cite":"28 Vt. 523","y":1856,"court":"Vt.","url":"https://www.courtlistener.com/c/Vt./28/523/","by":{"0":"28"}},{"t":"case","label":"Intel Corp. Inv. Pol’y Comm. v. Sulyma","cite":"140 S. Ct. 768","y":2020,"id":"2019/18-1116","sc":1,"op":1,"sum":"The Court held that under the Employee Retirement Income Security Act of 1974 requirement that plaintiffs with “actual knowledge” of an alleged fiduciary breach must file suit within three years of gaining that knowledge, a plaintiff does not necessarily have “actual knowledge” of the information contained in disclosures that he receives but does not read or cannot recall reading.","sumSrc":"Oyez","by":{"0":"31, 55","1":"17","2":"24","3":"17, 18"}},{"t":"case","label":"Jerman v. Carlisle, McNellie, Rini, Kramer & Ulrich LPA","cite":"559 U.S. 573","y":2010,"id":"2009/08-1200","sc":1,"op":1,"sum":"The Court held that a debt collector's mistake in interpreting the law cannot qualify for the Fair Debt Collection Practices Act bona fide error defense.","sumSrc":"Oyez","by":{"0":"41, 54","1":"16, 23"}},{"t":"case","label":"Kolstad v. Am. Dental Ass’n","cite":"527 U.S. 526","y":1999,"id":"1998/98-208","sc":1,"sum":"In a complicated split opinion, the Court held that if an employee can show their employer knowingly acted in violation of federal law then punitive damages may be sustained. The Court explained that the \"malice\" or \"reckless indifference\" standard applied to the relationship between employers and federal law, and is not a characterization of the severity threshold that the discrimination itself must meet.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Nieves v. Bartlett","cite":"139 S. Ct. 1715","y":2019,"id":"2018/17-1174","sc":1,"sum":"Because police officers had probable cause to arrest Bartlett, his First Amendment retaliatory arrest claim fails as a matter of law.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25"}},{"t":"case","label":"S.E.C. v. Big Apple Consulting USA, Inc.","cite":"783 F.3d 786","y":2015,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/783/786/","by":{"0":"35"}},{"t":"case","label":"Safeco Ins. Co. of Am. v. Burr","cite":"551 U.S. 47","y":2007,"id":"2006/06-84","sc":1,"op":14,"ar":18,"sum":"The Court ruled that insurance companies can be liable for willful violations of the Fair Credit Reporting Act if they show \"reckless disregard\" for the law. The justices held that the meaning of the term \"willful\" is contextually determined.","sumSrc":"Oyez","by":{"0":"14, 38, 39, 40, 41, 46","1":"10, 14, 22-25, 33","2":"2, 3, 24, 25, 30, 31, 32, 33, 39, 40, 41, 48, 49, 50","3":"1, 9, 12"}},{"t":"case","label":"Tantchev v. Garland","cite":"46 F.4th 431","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/46/431/","by":{"0":"35"}},{"t":"case","label":"Torres v. Madrid","cite":"141 S. Ct. 989","y":2021,"id":"2020/19-292","sc":1,"sum":"Application of physical force to the body of a person with intent to restrain is a seizure even if the person does not submit and is not subdued.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25"}},{"t":"case","label":"United States ex rel. Decesare v. Americare in Home Nursing","cite":"2011 WL 607390","y":2011,"court":"E.D. Va. Feb. 10","by":{"0":"37"}},{"t":"case","label":"United States ex rel. Garbe v. Kmart Corp.","cite":"73 F. Supp. 3d 1002","y":2014,"court":"S.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/73/1002/","by":{"0":"14","2":"16"}},{"t":"case","label":"United States ex rel. Garbe v. Kmart Corp.","cite":"824 F.3d 632","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/824/632/","by":{"0":"5, 13, 14","2":"16, 17","3":"3, 4"}},{"t":"case","label":"United States ex rel. Grubbs v. Kanneganti","cite":"565 F.3d 180","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/565/180/","by":{"0":"23"}},{"t":"case","label":"United States ex rel. Lynch v. Univ. of Cincinnati Med. Ctr., LLC","cite":"2020 WL 1322790","y":2020,"court":"S.D. Ohio Mar. 20","by":{"0":"37"}},{"t":"case","label":"United States ex rel. Ormsby v. Sutter Health","cite":"444 F. Supp. 3d 1010","y":2020,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/444/1010/","by":{"0":"37"}},{"t":"case","label":"United States ex rel. Prather v. Brookdale Senior Living Communities","cite":"892 F.3d 822","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/892/822/","by":{"0":"37"}},{"t":"case","label":"United States ex rel. Swoben v. United Healthcare Ins. Co.","cite":"848 F.3d 1161","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/848/1161/","by":{"0":"37"}},{"t":"case","label":"United States ex rel. Walker v. R&F Props. of Lake Cnty., Inc.","cite":"433 F.3d 1349","y":2005,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/433/1349/","by":{"0":"37"}},{"t":"case","label":"United States v. Bourseau","cite":"531 F.3d 1159","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/531/1159/","by":{"0":"37"}},{"t":"case","label":"United States v. Chen","cite":"402 F. App’x 185","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/402/185/","by":{"0":"37"}},{"t":"case","label":"United States v. Hong","cite":"938 F.3d 1040","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/938/1040/","by":{"0":"35"}},{"t":"case","label":"United States v. Neifert-White Co.","cite":"390 U.S. 228","y":1968,"id":"1967/267","sc":1,"sum":"The False Claims Act, which was enacted \"broadly to protect the funds and property of the Government from fraudulent claims, regardless of the particular form, or function, of the governmental instrumentality upon which such claims were made,\" Rainwater v. United States, 356 U. S. 590, 592 (1958), held to apply to the supplying of false information in support of an application to the Commodity Credit Corporation for …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3"}},{"t":"case","label":"United States v. Nektalov","cite":"461 F.3d 309","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/461/309/","by":{"0":"32"}},{"t":"case","label":"United States v. One 1973 Rolls Royce","cite":"43 F.3d 794","y":1994,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/43/794/","by":{"0":"32"}},{"t":"case","label":"United States v. One 1989 Jeep Wagoneer","cite":"976 F.2d 1172","y":1992,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/976/1172/","by":{"0":"35"}},{"t":"case","label":"United States v. Outreach Diagnostic Clinic LLP","cite":"2020 WL 1272609","y":2020,"court":"S.D. Tex. Mar. 16","by":{"0":"37"}},{"t":"case","label":"United States v. Raymond & Whitcomb Co.","cite":"53 F. Supp. 2d 436","y":1999,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/53/436/","by":{"0":"37"}},{"t":"case","label":"Universal Health Servs., Inc. v. United States ex rel. Escobar","cite":"579 U.S. 176","y":2016,"id":"2015/15-7","sc":1,"op":6,"sum":"The Court held that the implied certification test could be a valid basis for False Claims Act liability, and the conditions of payment with which the defendant allegedly failed to comply did not need to be explicitly stated.","sumSrc":"Oyez","by":{"0":"23, 24, 30, 36, 43","1":"20, 21","2":"3, 21, 27, 31, 33, 36, 39, 43, 44, 45, 52","3":"13"}},{"t":"case","label":"Viacom Int’l, Inc. v. YouTube, Inc.","cite":"676 F.3d 19","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/676/19/","by":{"0":"32"}},{"t":"usc","label":"15 U.S.C. § 1681n","url":"https://www.law.cornell.edu/uscode/text/15/1681n","subs":["(a)"],"stext":{"head":"§1681n. Civil liability for willful noncompliance","paras":[[0,"(a) In general"],[0,"Any person who willfully fails to comply with any requirement imposed under this subchapter with respect to any consumer is liable to that consumer in an amount equal to the sum of—"],[1,"(1)(A) any actual damages sustained by the consumer as a result of the failure or damages of not less than $100 and not more than $1,000; or"],[1,"(B) in the case of liability of a natural person for obtaining a consumer report under false pretenses or knowingly without a permissible purpose, actual damages sustained by the consumer as a result of the failure or $1,000, whichever is greater;"],[1,"(2) such amount of punitive damages as the court may allow; and"],[1,"(3) in the case of any successful action to enforce any liability under this section, the costs of the action together with reasonable attorney's fees as determined by the court."],[0,"(b) Civil liability for knowing noncompliance"],[0,"Any person who obtains a consumer report from a consumer reporting agency under false pretenses or knowingly without a permissible purpose shall be liable to the consumer reporting agency for actual damages sustained by the consumer reporting agency or $1,000, whichever is greater."],[0,"(c) Attorney's fees"],[0,"Upon a finding by the court that an unsuccessful pleading, motion, or other paper filed in connection with an action under this section was filed in bad faith or for purposes of harassment, the court shall award to the prevailing party attorney's fees reasonable in relation to the work expended in responding to the pleading, motion, or other paper."],[0,"(d) Clarification of willful noncompliance"],[0,"For the purposes of this section, any person who printed an expiration date on any receipt provided to a consumer cardholder at a point of sale or transaction between December 4, 2004, and June 3, 2008, but otherwise complied with the requirements of section 1681c(g) of this title for such receipt shall not be in willful noncompliance with section 1681c(g) of this title by reason of printing such expiration date on the receipt."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1681n?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1681n. Civil liability for willful noncompliance","tname":"Commerce and Trade","by":{"0":"39, 42, 46","1":"10, 14, 22, 24"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"31 U.S.C. § 3729","url":"https://www.law.cornell.edu/uscode/text/31/3729","subs":["(a)(1)","(a)(1)(A)","(b)(1)","(b)(1)(A)","(b)(1)(A)(iii)","(b)(1)(B)","(1)","(a)(1)(B)","(a)(1)(G)","(b)(1)(A)(i)","(b)(1)(A)(ii)","(b)(2)(A)(i)","(b)(2)(A)(ii)","(b)(4)"],"stext":{"head":"§3729. False claims","paras":[[0,"(a) Liability for Certain Acts.—"],[1,"(1) In general.—Subject to paragraph (2), any person who—"],[2,"(A) knowingly presents, or causes to be presented, a false or fraudulent claim for payment or approval;"],[2,"(B) knowingly makes, uses, or causes to be made or used, a false record or statement material to a false or fraudulent claim;"],[2,"(C) conspires to commit a violation of subparagraph (A), (B), (D), (E), (F), or (G);"],[2,"(D) has possession, custody, or control of property or money used, or to be used, by the Government and knowingly delivers, or causes to be delivered, less than all of that money or property;"],[2,"(E) is authorized to make or deliver a document certifying receipt of property used, or to be used, by the Government and, intending to defraud the Government, makes or delivers the receipt without completely knowing that the information on the receipt is true;"],[2,"(F) knowingly buys, or receives as a pledge of an obligation or debt, public property from an officer or employee of the Government, or a member of the Armed Forces, who lawfully may not sell or pledge property; or"],[2,"(G) knowingly makes, uses, or causes to be made or used, a false record or statement material to an obligation to pay or transmit money or property to the Government, or knowingly conceals or knowingly and improperly avoids or decreases an obligation to pay or transmit money or property to the Government,"],[1,"is liable to the United States Government for a civil penalty of not less than $5,000 and not more than $10,000, as adjusted by the Federal Civil Penalties Inflation Adjustment Act of 1990 (28 U.S.C. 2461 note; Public Law 104–410 1), plus 3 times the amount of damages which the Government sustains because of the act of that person."],[1,"(2) Reduced damages.—If the court finds that—"],[2,"(A) the person committing the violation of this subsection furnished officials of the United States responsible for investigating false claims violations with all information known to such person about the violation within 30 days after the date on which the defendant first obtained the information;"],[2,"(B) such person fully cooperated with any Government investigation of such violation; and"],[2,"(C) at the time such person furnished the United States with the information about the violation, no criminal prosecution, civil action, or administrative action had commenced under this title with respect to such violation, and the person did not have actual knowledge of the existence of an investigation into such violation,"],[1,"the court may assess not less than 2 times the amount of damages which the Government sustains because of the act of that person."],[1,"(3) Costs of civil actions.—A person violating this subsection shall also be liable to the United States Government for the costs of a civil action brought to recover any such penalty or damages."],[0,"(b) Definitions.—For purposes of this section—"],[1,"(1) the terms \"knowing\" and \"knowingly\"—"],[2,"(A) mean that a person, with respect to information—"],[3,"(i) has actual knowledge of the information;"],[3,"(ii) acts in deliberate ignorance of the truth or falsity of the information; or"],[3,"(iii) acts in reckless disregard of the truth or falsity of the information; and"],[2,"(B) require no proof of specific intent to defraud;"],[1,"(2) the term \"claim\"—"],[2,"(A) means any request or demand, whether under a contract or otherwise, for money or property and whether or not the United States has title to the money or property, that—"],[3,"(i) is presented to an officer, employee, or agent of the United States; or"],[3,"(ii) is made to a contractor, grantee, or other recipient, if the money or property is to be spent or used on the Government's behalf or to advance a Government program or interest, and if the United States Government—"],[4,"(I) provides or has provided any portion of the money or property requested or demanded; or"],[4,"(II) will reimburse such contractor, grantee, or other recipient for any portion of the money or property which is requested or demanded; and"],[2,"(B) does not include requests or demands for money or property that the Government has paid to an individual as compensation for Federal employment or as an income subsidy with no restrictions on that individual's use of the money or property;"],[1,"(3) the term \"obligation\" means an established duty, whether or not fixed, arising from an express or implied contractual, grantor-grantee, or licensor-licensee relationship, from a fee-based or similar relationship, from statute or regulation, or from the retention of any overpayment; and"],[1,"(4) the term \"material\" means having a natural tendency to influence, or be capable of influencing, the payment or receipt of money or property."],[0,"(c) Exemption From Disclosure.—Any information furnished pursuant to subsection (a)(2) shall be exempt from disclosure under section 552 of title 5."],[0,"(d) Exclusion.—This section does not apply to claims, records, or statements made under the Internal Revenue Code of 1986."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3729?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§3729. False claims","tname":"Money and Finance","by":{"0":"2, i, 3, 23, 31, 42, 2, i, 3, 42, 43, 44, 3, 23","1":"1, 16, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 33, 15","2":"23, 39","3":"16, 1, 8, 18"}},{"t":"reg","label":"42 C.F.R. § 447.512","url":"https://www.ecfr.gov/current/title-42/section-447.512","subs":["(b)"],"by":{"0":"5"}},{"t":"case","label":"Godecke v. Kinetic Concepts, Inc.","cite":"937 F.3d 1201","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/937/1201/","by":{"1":"18"}},{"t":"case","label":"Rock Island, Arkansas & Louisiana Railroad Co. v. United States","cite":"254 U.S. 141","y":1920,"id":"scdb/1920-032","sc":1,"sum":"The right to sue for the recovery of an internal revenue tax illegally assessed is conditioned upon prior appeal to and decision by the-Commissioner of Internal Revenue, which means an appeal, after payment, for a refund, and is not satisfied by an appeal or application for abatement of the tax before it was paid. Rev. Stats., §§ 3226 (as amended), 3220, 3228, construed.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"United States v. Aerodex, Inc.","cite":"469 F.2d 1003","y":1972,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/469/1003/","by":{"1":"16"}},{"t":"case","label":"United States v. Ricard","cite":"922 F.3d 639","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/922/639/","by":{"1":"17"}},{"t":"case","label":"United States ex rel. Phalp v. Lincare Holdings, Inc.","cite":"857 F.3d 1148","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/857/1148/","by":{"1":"18"}},{"t":"case","label":"United States ex rel. Polukoff v. St. Mark’s Hospital","cite":"895 F.3d 730","y":2018,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/895/730/","by":{"1":"18"}},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","by":{"1":"19"}},{"t":"usc","label":"15 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/15/1681","by":{"1":"22"}},{"t":"usc","label":"15 U.S.C. § 1681m","url":"https://www.law.cornell.edu/uscode/text/15/1681m","subs":["(a)"],"by":{"1":"22"}},{"t":"usc","label":"31 U.S.C. § 3730","url":"https://www.law.cornell.edu/uscode/text/31/3730","subs":["(a)","(b)","(b)(2)","(b)(3)","(b)(4)(B)","(d)","(c)(2)(A)","(d)(4)","(g)"],"stext":{"head":"§3730. Civil actions for false claims","paras":[[0,"(a) Responsibilities of the Attorney General.—The Attorney General diligently shall investigate a violation under section 3729. If the Attorney General finds that a person has violated or is violating section 3729, the Attorney General may bring a civil action under this section against the person."],[0,"(b) Actions by Private Persons.—(1) A person may bring a civil action for a violation of section 3729 for the person and for the United States Government. The action shall be brought in the name of the Government. The action may be dismissed only if the court and the Attorney General give written consent to the dismissal and their reasons for consenting."],[0,"(2) A copy of the complaint and written disclosure of substantially all material evidence and information the person possesses shall be served on the Government pursuant to Rule 4(d)(4) 1 of the Federal Rules of Civil Procedure. The complaint shall be filed in camera, shall remain under seal for at least 60 days, and shall not be served on the defendant until the court so orders. The Government may elect to intervene and proceed with the action within 60 days after it receives both the complaint and the material evidence and information."],[0,"(3) The Government may, for good cause shown, move the court for extensions of the time during which the complaint remains under seal under paragraph (2). Any such motions may be supported by affidavits or other submissions in camera. The defendant shall not be required to respond to any complaint filed under this section until 20 days after the complaint is unsealed and served upon the defendant pursuant to Rule 4 of the Federal Rules of Civil Procedure."],[0,"(4) Before the expiration of the 60-day period or any extensions obtained under paragraph (3), the Government shall—"],[1,"(A) proceed with the action, in which case the action shall be conducted by the Government; or"],[1,"(B) notify the court that it declines to take over the action, in which case the person bringing the action shall have the right to conduct the action."],[0,"(5) When a person brings an action under this subsection, no person other than the Government may intervene or bring a related action based on the facts underlying the pending action."],[0,"(c) Rights of the Parties to Qui Tam Actions.—(1) If the Government proceeds with the action, it shall have the primary responsibility for prosecuting the action, and shall not be bound by an act of the person bringing the action. Such person shall have the right to continue as a party to the action, subject to the limitations set forth in paragraph (2)."],[0,"(2)(A) The Government may dismiss the action notwithstanding the objections of the person initiating the action if the person has been notified by the Government of the filing of the motion and the court has provided the person with an opportunity for a hearing on the motion."],[0,"(B) The Government may settle the action with the defendant notwithstanding the objections of the person initiating the action if the court determines, after a hearing, that the proposed settlement is fair, adequate, and reasonable under all the circumstances. Upon a showing of good cause, such hearing may be held in camera."],[0,"(C) Upon a showing by the Government that unrestricted participation during the course of the litigation by the person initiating the action would interfere with or unduly delay the Government's prosecution of the case, or would be repetitious, irrelevant, or for purposes of harassment, the court may, in its discretion, impose limitations on the person's participation, such as—"],[1,"(i) limiting the number of witnesses the person may call;"],[1,"(ii) limiting the length of the testimony of such witnesses;"],[1,"(iii) limiting the person's cross-examination of witnesses; or"],[1,"(iv) otherwise limiting the participation by the person in the litigation."],[0,"(D) Upon a showing by the defendant that unrestricted participation during the course of the litigation by the person initiating the action would be for purposes of harassment or would cause the defendant undue burden or unnecessary expense, the court may limit the participation by the person in the litigation."],[0,"(3) If the Government elects not to proceed with the action, the person who initiated the action shall have the right to conduct the action. If the Government so requests, it shall be served with copies of all pleadings filed in the action and shall be supplied with copies of all deposition transcripts (at the Government's expense). When a person proceeds with the action, the court, without limiting the status and rights of the person initiating the action, may nevertheless permit the Government to intervene at a later date upon a showing of good cause."],[0,"(4) Whether or not the Government proceeds with the action, upon a showing by the Government that certain actions of discovery by the person initiating the action would interfere with the Government's investigation or prosecution of a criminal or civil matter arising out of the same facts, the court may stay such discovery for a period of not more than 60 days. Such a showing shall be conducted in camera. The court may extend the 60-day period upon a further showing in camera that the Government has pursued the criminal or civil investigation or proceedings with reasonable diligence and any proposed discovery in the civil action will interfere with the ongoing criminal or civil investigation or proceedings."],[0,"(5) Notwithstanding subsection (b), the Government may elect to pursue its claim through any alternate remedy available to the Government, including any administrative proceeding to determine a civil money penalty. If any such alternate remedy is pursued in another proceeding, the person initiating the action shall have the same rights in such proceeding as such person would have had if the action had continued under this section. Any finding of fact or conclusion of law made in such other proceeding that has become final shall be conclusive on all parties to an action under this section. For purposes of the preceding sentence, a finding or conclusion is final if it has been finally determined on appeal to the appropriate court of the United States, if all time for filing such an appeal with respect to the finding or conclusion has expired, or if the finding or conclusion is not subject to judicial review."],[0,"(d) Award to Qui Tam Plaintiff.—(1) If the Government proceeds with an action brought by a person under subsection (b), such person shall, subject to the second sentence of this paragraph, receive at least 15 percent but not more than 25 percent of the proceeds of the action or settlement of the claim, depending upon the extent to which the person substantially contributed to the prosecution of the action. Where the action is one which the court finds to be based primarily on disclosures of specific information (other than information provided by the person bringing the action) relating to allegations or transactions in a criminal, civil, or administrative hearing, in a congressional, administrative, or Government 2 Accounting Office report, hearing, audit, or investigation, or from the news media, the court may award such sums as it considers appropriate, but in no case more than 10 percent of the proceeds, taking into account the significance of the information and the role of the person bringing the action in advancing the case to litigation. Any payment to a person under the first or second sentence of this paragraph shall be made from the proceeds. Any such person shall also receive an amount for reasonable expenses which the court finds to have been necessarily incurred, plus reasonable attorneys' fees and costs. All such expenses, fees, and costs shall be awarded against the defendant."],[0,"(2) If the Government does not proceed with an action under this section, the person bringing the action or settling the claim shall receive an amount which the court decides is reasonable for collecting the civil penalty and damages. The amount shall be not less than 25 percent and not more than 30 percent of the proceeds of the action or settlement and shall be paid out of such proceeds. Such person shall also receive an amount for reasonable expenses which the court finds to have been necessarily incurred, plus reasonable attorneys' fees and costs. All such expenses, fees, and costs shall be awarded against the defendant."],[0,"(3) Whether or not the Government proceeds with the action, if the court finds that the action was brought by a person who planned and initiated the violation of section 3729 upon which the action was brought, then the court may, to the extent the court considers appropriate, reduce the share of the proceeds of the action which the person would otherwise receive under paragraph (1) or (2) of this subsection, taking into account the role of that person in advancing the case to litigation and any relevant circumstances pertaining to the violation. If the person bringing the action is convicted of criminal conduct arising from his or her role in the violation of section 3729, that person shall be dismissed from the civil action and shall not receive any share of the proceeds of the action. Such dismissal shall not prejudice the right of the United States to continue the action, represented by the Department of Justice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3730?type=usc&year=mostrecent&link-type=html"},"head":"§3730. Civil actions for false claims","tname":"Money and Finance","by":{"1":"2, 2, 2, 2, 2, 2","3":"26, 27, 27"}},{"t":"law","label":"Pub. L. No. 99-562","url":"https://www.govinfo.gov/link/statute/100/3153","by":{"1":"17"}},{"t":"usc","label":"42 U.S.C. § 1396","url":"https://www.law.cornell.edu/uscode/text/42/1396","stext":{"head":"§1396. Medicaid and CHIP Payment and Access Commission","paras":[[0,"(a) Establishment"],[0,"There is hereby established the Medicaid and CHIP Payment and Access Commission (in this section referred to as \"MACPAC\")."],[0,"(b) Duties"],[0,"(1) Review of access policies for all States and annual reports"],[1,"MACPAC shall—"],[2,"(A) review policies of the Medicaid program established under this subchapter (in this section referred to as \"Medicaid\") and the State Children's Health Insurance Program established under subchapter XXI (in this section referred to as \"CHIP\") affecting access to covered items and services, including topics described in paragraph (2);"],[2,"(B) make recommendations to Congress, the Secretary, and States concerning such access policies;"],[2,"(C) by not later than March 15 of each year (beginning with 2010), submit a report to Congress containing the results of such reviews and MACPAC's recommendations concerning such policies; and"],[2,"(D) by not later than June 15 of each year (beginning with 2010), submit a report to Congress containing an examination of issues affecting Medicaid and CHIP, including the implications of changes in health care delivery in the United States and in the market for health care services on such programs."],[0,"(2) Specific topics to be reviewed"],[1,"Specifically, MACPAC shall review and assess the following:"],[0,"(A) Medicaid and CHIP payment policies"],[2,"Payment policies under Medicaid and CHIP, including—"],[3,"(i) the factors affecting expenditures for the efficient provision of items and services in different sectors, including the process for updating payments to medical, dental, and health professionals, hospitals, residential and long-term care providers, providers of home and community based services, Federally-qualified health centers and rural health clinics, managed care entities, and providers of other covered items and services;"],[3,"(ii) payment methodologies; and"],[3,"(iii) the relationship of such factors and methodologies to access and quality of care for Medicaid and CHIP beneficiaries (including how such factors and methodologies enable such beneficiaries to obtain the services for which they are eligible, affect provider supply, and affect providers that serve a disproportionate share of low-income and other vulnerable populations)."],[0,"(B) Eligibility policies"],[2,"Medicaid and CHIP eligibility policies, including a determination of the degree to which Federal and State policies provide health care coverage to needy populations."],[0,"(C) Enrollment and retention processes"],[2,"Medicaid and CHIP enrollment and retention processes, including a determination of the degree to which Federal and State policies encourage the enrollment of individuals who are eligible for such programs and screen out individuals who are ineligible, while minimizing the share of program expenses devoted to such processes."],[0,"(D) Coverage policies"],[2,"Medicaid and CHIP benefit and coverage policies, including a determination of the degree to which Federal and State policies provide access to the services enrollees require to improve and maintain their health and functional status."],[0,"(E) Quality of care"],[2,"Medicaid and CHIP policies as they relate to the quality of care provided under those programs, including a determination of the degree to which Federal and State policies achieve their stated goals and interact with similar goals established by other purchasers of health care services."],[0,"(F) Interaction of Medicaid and CHIP payment policies with health care delivery generally"],[2,"The effect of Medicaid and CHIP payment policies on access to items and services for children and other Medicaid and CHIP populations other than under this subchapter or subchapter XXI and the implications of changes in health care delivery in the United States and in the general market for health care items and services on Medicaid and CHIP."],[0,"(G) Interactions with Medicare and Medicaid"],[2,"Consistent with paragraph (11), the interaction of policies under Medicaid and the Medicare program under subchapter XVIII, including with respect to how such interactions affect access to services, payments, and dual eligible individuals."],[0,"(H) Other access policies"],[2,"The effect of other Medicaid and CHIP policies on access to covered items and services, including policies relating to transportation and language barriers and preventive, acute, and long-term services and supports."],[0,"(3) Recommendations and reports of State-specific data"],[1,"MACPAC shall—"],[2,"(A) review national and State-specific Medicaid and CHIP data; and"],[2,"(B) submit reports and recommendations to Congress, the Secretary, and States based on such reviews."],[0,"(4) Creation of early-warning system"],[1,"MACPAC shall create an early-warning system to identify provider shortage areas, as well as other factors that adversely affect, or have the potential to adversely affect, access to care by, or the health care status of, Medicaid and CHIP beneficiaries. MACPAC shall include in the annual report required under paragraph (1)(D) a description of all such areas or problems identified with respect to the period addressed in the report."],[0,"(5) Comments on certain secretarial reports and regulations"],[0,"(A) Certain secretarial reports"],[2,"If the Secretary submits to Congress (or a committee of Congress) a report that is required by law and that relates to access policies, including with respect to payment policies, under Medicaid or CHIP, the Secretary shall transmit a copy of the report to MACPAC. MACPAC shall review the report and, not later than 6 months after the date of submittal of the Secretary's report to Congress, shall submit to the appropriate committees of Congress and the Secretary written comments on such report. Such comments may include such recommendations as MACPAC deems appropriate."],[0,"(B) Regulations"],[2,"MACPAC shall review Medicaid and CHIP regulations and may comment through submission of a report to the appropriate committees of Congress and the Secretary, on any such regulations that affect access, quality, or efficiency of health care."],[0,"(6) Agenda and additional reviews"],[0,"(A) In general"],[2,"MACPAC shall consult periodically with the chairmen and ranking minority members of the appropriate committees of Congress regarding MACPAC's agenda and progress towards achieving the agenda. MACPAC may conduct additional reviews, and submit additional reports to the appropriate committees of Congress, from time to time on such topics relating to the program under this subchapter or subchapter XXI as may be requested by such chairmen and members and as MACPAC deems appropriate."],[0,"(B) Review and reports regarding Medicaid DSH"],[0,"(i) In general"],[3,"MACPAC shall review and submit an annual report to Congress on disproportionate share hospital payments under section 1396r–4 of this title. Each report shall include the information specified in clause (ii)."],[0,"(ii) Required report information"],[3,"Each report required under this subparagraph shall include the following:"],[4,"(I) Data relating to changes in the number of uninsured individuals."],[4,"(II) Data relating to the amount and sources of hospitals' uncompensated care costs, including the amount of such costs that are the result of providing unreimbursed or under-reimbursed services, charity care, or bad debt."],[4,"(III) Data identifying hospitals with high levels of uncompensated care that also provide access to essential community services for low-income, uninsured, and vulnerable populations, such as graduate medical education, and the continuum of primary through quarternary care, including the provision of trauma care and public health services."],[4,"(IV) State-specific analyses regarding the relationship between the most recent State DSH allotment and the projected State DSH allotment for the succeeding year and the data reported under subclauses (I), (II), and (III) for the State."],[0,"(iii) Data"],[3,"Notwithstanding any other provision of law, the Secretary regularly shall provide MACPAC with the most recent State reports and most recent independent certified audits submitted under section 1396r–4(j) of this title, cost reports submitted under subchapter XVIII, and such other data as MACPAC may request for purposes of conducting the reviews and preparing and submitting the annual reports required under this subparagraph."],[0,"(iv) Submission deadlines"],[3,"The first report required under this subparagraph shall be submitted to Congress not later than February 1, 2016. Subsequent reports shall be submitted as part of, or with, each annual report required under paragraph (1)(C) during the period of fiscal years 2017 through 2024."],[0,"(7) Availability of reports"],[1,"MACPAC shall transmit to the Secretary a copy of each report submitted under this subsection and shall make such reports available to the public."],[0,"(8) Appropriate committee of Congress"],[1,"For purposes of this section, the term \"appropriate committees of Congress\" means the Committee on Energy and Commerce of the House of Representatives and the Committee on Finance of the Senate."],[0,"(9) Voting and reporting requirements"],[1,"With respect to each recommendation contained in a report submitted under paragraph (1), each member of MACPAC shall vote on the recommendation, and MACPAC shall include, by member, the results of that vote in the report containing the recommendation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1396. Medicaid and CHIP Payment and Access Commission","tname":"The Public Health and Welfare","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 1396d","url":"https://www.law.cornell.edu/uscode/text/42/1396d","subs":["(a)(12)"],"by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 1395","url":"https://www.law.cornell.edu/uscode/text/42/1395","stext":{"head":"§1395. Prohibition against any Federal interference","paras":[[0,"Nothing in this subchapter shall be construed to authorize any Federal officer or employee to exercise any supervision or control over the practice of medicine or the manner in which medical services are provided, or over the selection, tenure, or compensation of any officer or employee of any institution, agency, or person providing health services; or to exercise any supervision or control over the administration or operation of any such institution, agency, or person."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1395. Prohibition against any Federal interference","tname":"The Public Health and Welfare","by":{"1":"3"}},{"t":"usc","label":"42 U.S.C. § 1395w-101","url":"https://www.law.cornell.edu/uscode/text/42/1395w-101","by":{"1":"2, 3, 5, 6, 9, 15"}},{"t":"usc","label":"42 U.S.C. § 1395w-111","url":"https://www.law.cornell.edu/uscode/text/42/1395w-111","subs":["(i)"],"by":{"1":"4"}},{"t":"case","label":"Abbott v. Treat","cite":"3 A. 44","y":1886,"court":"Me.","url":"https://www.courtlistener.com/c/A./3/44/","by":{"2":"36"}},{"t":"case","label":"Alaska Dep’t of Env’t Conservation v. EPA","cite":"540 U.S. 461","y":2004,"id":"2003/02-658","sc":1,"op":1,"sum":"The Court held that the Clean Air Act authorized the EPA to bar the construction of the polluting facility in Alaska. Though Alaska determined the facility's use of \"Low NOx\" met the act's requirement that facilities use \"best available control technology,\" the EPA was reasonable to reject this claim.","sumSrc":"Oyez","by":{"2":"51"}},{"t":"case","label":"Anderson v. Modica","cite":"73 A.2d 49","y":1950,"court":"N.J.","url":"https://www.courtlistener.com/c/A.2d/73/49/","by":{"2":"35"}},{"t":"case","label":"Ark. Dep’t of Health & Hum. Servs. v. Ahl- born","cite":"547 U.S. 268","y":2006,"id":"2005/04-1506","sc":1,"sum":"The Court ruled that federal Medicaid statutes only allow a state to recover the part of a third-party settlement earmarked for medical expenses. The Justices agreed with the Circuit Court that the statutes do not permit Arkansas to require Ahlborn to repay Medicare expenses from the non-medical portions of the settlement.","sumSrc":"Oyez","by":{"2":"6"}},{"t":"case","label":"Bittner v. United States","cite":"143 S. Ct. 713","y":2023,"id":"2022/21-1195","sc":1,"sum":"The Bank Secrecy Act’s $10,000 maximum penalty for the nonwillful failure to file a compliant report accrues on a per-report, not a per-account, basis.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"46"}},{"t":"case","label":"Buffington v. McDonough","cite":"143 S. Ct. 14","y":2022,"url":"https://www.courtlistener.com/c/S.%20Ct./143/14/","sc":1,"by":{"2":"35, 51"}},{"t":"case","label":"Christensen v. Harris Cnty.","cite":"529 U.S. 576","y":2000,"id":"1999/98-1167","sc":1,"sum":"The Court held 6-3 that \"[n]othing in the FLSA or its implementing regulations prohibits a public employer from compelling the use of compensatory time.\" Justice Thomas wrote for the Court that, \"under the FLSA, an employer is free to require an employee to take time off work, and an employer is also free to use the money it would have paid in wages to cash out accrued compensatory time.","sumSrc":"Oyez","by":{"2":"49"}},{"t":"case","label":"Christopher v. SmithKline Beecham Corp.","cite":"567 U.S. 142","y":2012,"id":"2011/11-204","sc":1,"op":1,"sum":"The Court held that the Secretary of Labor's definition of \"outside salesman\" apply to pharmaceutical sales representatives under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"2":"42, 45, 46, 50"}},{"t":"case","label":"Comer v. Life Ins. Co. of Ala.","cite":"2010 WL 2232204","y":2010,"court":"D.S.C. June 2","sum":"Finding the term “charge” “patently ambiguous because it is susceptible of more than one meaning”.","sumSrc":"brief:2","by":{"2":"12"}},{"t":"case","label":"Dep’t of Homeland Sec. v. Regents of the Univ. of Cal.","cite":"140 S. Ct. 1891","y":2020,"id":"2019/18-587","sc":1,"sum":"The Court held that the Department of Homeland Security’s decision to rescind the Deferred Action for Childhood Arrivals program was arbitrary and capricious under the Administrative Procedure Act.","sumSrc":"Oyez","by":{"2":"33"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Servs., Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"sum":"The Court ruled that as long one plaintiff meets the amount-in-controversy requirement for federal jurisdiction, Section 1367 authorizes federal courts to exercise supplemental jurisdiction over related claims even if they do not meet the requirement.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"FCC v. Fox Television Stations, Inc.","cite":"567 U.S. 239","y":2012,"id":"2011/10-1293","sc":1,"sum":"The Court determined that an FCC policy regarding profane language was too vague, and which was remanded to the Second Circuit Court of Appeals to determine if the FCC violated its customers' First Amendment rights.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"Gates & Fox Co. v. Occupational Safety & Health Rev. Comm’n","cite":"790 F.2d 154","y":1986,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/790/154/","by":{"2":"45"}},{"t":"case","label":"Harris v. Delco Prods.","cite":"25 N.E.2d 740","y":1940,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E.2d/25/740/","by":{"2":"35"}},{"t":"case","label":"Heien v. North Carolina","cite":"574 U.S. 54","y":2014,"id":"2014/13-604","sc":1,"sum":"The Court decided that search and seizures are acceptable if a police officer made a reasonable factual or legal mistake.","sumSrc":"Oyez","by":{"2":"48"}},{"t":"case","label":"Holland v. Trinity Health Care Corp.","cite":"791 N.W. 2d 724","y":2010,"court":"Mich. Ct. App.","url":"https://www.courtlistener.com/c/N.W.%202d/791/724/","by":{"2":"12, 55"}},{"t":"case","label":"Hughes Aircraft Co. v. United States ex rel. Schumer","cite":"520 U.S. 939","y":1997,"id":"1996/95-1340","sc":1,"sum":"The Court held that, because the 1986 amendment does not apply retroactively to qui tam suits regarding allegedly false claims submitted prior to its enactment, Schumer's action should have been dismissed, as required by the pre-1986 version of the FCA.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"Iron Silver Mining Co. v. Reynolds","cite":"124 U.S. 374","y":1888,"id":"scdb/1887-120","sc":1,"sum":"Plaintiff’s complaint alleged that he was owner and in possession of a tract of mining land described by metes and bounds and known as the Wells and Moyer placer claim, and that while he was thus owner and possessor defendant entered upon a.portion of it and wrongfully ousted him therefrom. Defendant denied these allegations and set up that at' the times named he was owner and in possession of two lode mining claims …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"24, 40, 41","3":"18"}},{"t":"case","label":"Kisor v. Wilkie","cite":"139 S. Ct. 2400","y":2019,"id":"2018/18-15","sc":1,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"28, 45, 49, 50, 53","3":"22"}},{"t":"case","label":"Klaczak v. Consol. Med. Transp.","cite":"458 F. Supp. 2d 622","y":2006,"court":"N.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/458/622/","by":{"2":"12"}},{"t":"case","label":"Meacham v. Halley","cite":"103 F.2d 967","y":1939,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/103/967/","by":{"2":"36"}},{"t":"case","label":"Rehab. Ass’n of Va., Inc. v. Kozlowski","cite":"42 F.3d 1444","y":1994,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/42/1444/","by":{"2":"54"}},{"t":"case","label":"Screws v. United States","cite":"325 U.S. 91","y":1945,"id":"scdb/1944-039","sc":1,"sum":"1. Upon review of a judgment affirming the conviction, for violation of § 20 of the Criminal Code and conspiracy thereunto, of local law-enforcement officers who arrested a negro citizen for a state offense and wrongfully beat him to death, the judgment is reversed with directions for a new trial. Pp. 92-94, 113. Opinion of DOUGLAS, J., in which the CHIEF JUSTICE, MR. JUSTICE BLAcK and MR. JUSTICE REED concur:","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24, 25","3":"18"}},{"t":"case","label":"Sessions v. Dimaya","cite":"138 S. Ct. 1204","y":2018,"id":"2017/15-1498","sc":1,"sum":"A case in which the Court struck down the Immigration and Nationality Act’s “crime of violence” provision as unconstitutionally vague in violation of the Due Process Clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"Page Skidmore v. Swift & Co.","cite":"323 U.S. 134","y":1944,"id":"1940-1955/12","sc":1,"sum":"The Court held that there was no reason that time spent waiting could not also be time spent working, especially in cases in which the conditions of employment involve waiting time. Although it can be difficult to determine the facts of a case and whether the activity in question constitutes work, Congress granted the courts the authority to do so.","sumSrc":"Oyez","by":{"2":"51"}},{"t":"case","label":"Sorensen v. Gardner","cite":"334 P.2d 471","y":1959,"court":"Or.","url":"https://www.courtlistener.com/c/P.2d/334/471/","op":1,"by":{"2":"36"}},{"t":"case","label":"United States ex rel. K & R Ltd. P’ship v. Mass. Hous. Fin. Agency","cite":"530 F.3d 980","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/530/980/","by":{"2":"52"}},{"t":"case","label":"United States ex rel. Marcus v. Hess","cite":"317 U.S. 537","y":1943,"id":"scdb/1942-043","sc":1,"sum":"1. Section 5438 of the Revised Statutes, which subjects to the penalties therein prescribed \"Every person who.. causes to be presented, for payment... any claim upon or against the Government of the United States,... knowing such claim to be.. fraudulent...,\" held applicable to contractors who, by collusive bidding, obtained contracts with municipalities and school districts of a State for work on federal Public …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"47"}},{"t":"case","label":"United States ex rel. Purcell v. MWI Corp.","cite":"807 F.3d 281","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/807/281/","by":{"2":"1, 25, 30"}},{"t":"case","label":"United States ex rel. Sheldon v. Allergan Sales, LLC","cite":"24 F.4th 340","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/24/340/","by":{"2":"34, 43, 48, 49, 50, 52"}},{"t":"case","label":"United States ex rel. Siewick v. Jamieson Sci. & Eng’g, Inc.","cite":"214 F.3d 1372","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/214/1372/","by":{"2":"25, 28"}},{"t":"case","label":"United States ex rel. Streck v. Allergan, Inc.","cite":"746 F. App’x 101","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/746/101/","by":{"2":"50"}},{"t":"case","label":"Page United States ex rel. Wilkins v. United Health Grp., Inc.","cite":"659 F.3d 295","y":2011,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/659/295/","by":{"2":"54"}},{"t":"case","label":"United States v. Bruno’s Inc.","cite":"54 F. Supp. 2d 1252","y":1999,"court":"M.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/54/1252/","by":{"2":"12, 55"}},{"t":"case","label":"United States v. Moore","cite":"612 F.3d 698","y":2010,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/612/698/","by":{"2":"44"}},{"t":"case","label":"United States v. Santos","cite":"553 U.S. 507","y":2008,"id":"2007/06-1005","sc":1,"sum":"Splitting 5 to 4, the Court affirmed the Seventh Circuit, answering that \"proceeds\" refers to \"net income\" or profits and not to \"gross income.\" Because the statute nowhere defines the term \"proceeds\", the plurality applied the so-called rule of lenity which requires such ambiguous statutes to be interpreted in favor of defendants.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"United States v. Winstar Corp.","cite":"518 U.S. 839","y":1996,"id":"1995/95-865","sc":1,"sum":"In a 7-2 plurality opinion delivered Justice David H. Souter, the Court held that the terms assigning the risk of regulatory change to the Government are enforceable and that the Government is therefore liable in damages for breach, although Congress changed the relevant law, and thereby barred the Government from specifically honoring its agreements.","sumSrc":"Oyez","by":{"2":"33"}},{"t":"case","label":"Upjohn Co. v. United States","cite":"449 U.S. 383","y":1981,"id":"1980/79-886","sc":1,"sum":"When the General Counsel for petitioner pharmaceutical 'manufacturing corporation (hereafter petitioner) was informed that one of its foreign subsidiaries had made questionable payments to foreign government officials in order to secure government business, an internal investigation of such payments was initiated. As part of this investigation, petitioner's attorneys sent a questionnaire to all foreign managers …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"54"}},{"t":"case","label":"Upton v. Tribilcock","cite":"91 U.S. 45","y":1875,"id":"scdb/1875-010","sc":1,"by":{"2":"35"}},{"t":"case","label":"White v. Harrigan","cite":"186 P. 224","y":1919,"court":"Okla.","url":"https://www.courtlistener.com/c/P./186/224/","by":{"2":"36"}},{"t":"case","label":"Wooden v. United States","cite":"142 S. Ct. 1063","y":2022,"id":"2021/20-5279","sc":1,"sum":"Wooden’s ten burglary offenses arising from a single criminal episode did not occur on different “occasions” and thus count as only one prior conviction under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"46"}},{"t":"usc","label":"18 U.S.C. § 287","url":"https://www.law.cornell.edu/uscode/text/18/287","by":{"2":"46"}},{"t":"usc","label":"42 U.S.C. § 1302","url":"https://www.law.cornell.edu/uscode/text/42/1302","by":{"2":"6"}},{"t":"usc","label":"42 U.S.C. § 1396-1","url":"https://www.law.cornell.edu/uscode/text/42/1396-1","by":{"2":"7"}},{"t":"reg","label":"42 C.F.R. § 423.100","url":"https://www.ecfr.gov/current/title-42/section-423.100","by":{"2":"8"}},{"t":"reg","label":"40 Fed. Reg. 34,516","url":"https://www.govinfo.gov/link/fr/40/34516","by":{"2":"6"}},{"t":"reg","label":"43 Fed. Reg. 45,176","url":"https://www.govinfo.gov/link/fr/43/45176","by":{"2":"6"}},{"t":"reg","label":"70 Fed. Reg. 4194","url":"https://www.govinfo.gov/link/fr/70/4194","by":{"2":"9, 11"}},{"t":"reg","label":"72 Fed. Reg. 39,142","url":"https://www.govinfo.gov/link/fr/72/39142","by":{"2":"6"}},{"t":"reg","label":"74 Fed. Reg. 54,634","url":"https://www.govinfo.gov/link/fr/74/54634","by":{"2":"9"}},{"t":"case","label":"Cheek v. United States","cite":"498 U.S. 192","y":1991,"id":"1990/89-658","sc":1,"sum":"Petitioner Cheek was charged with six counts of willfully failing to file a federal income tax return in violation of § 7203 of the Internal Revenue Code (Code) and three counts of willfully attempting to evade his income taxes in violation of §7201. Although admitting that he had not filed his returns, he testified that he had not acted willfully because he sincerely believed, based on his indoctrination by a group …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"27"}},{"t":"case","label":"Cochise Consultancy, Inc. v. United States ex rel. Hunt","cite":"139 S. Ct. 1507","y":2019,"id":"2018/18-315","sc":1,"sum":"The limitations period in 31 U. S. C. §3731(b)(2)—which provides that a False Claims Act action must be brought within 3 years after the “the official of the United States charged with responsibility to act in the circumstances” knew or should have known the relevant facts, but not more than 10 years after the violation—applies in a qui tam suit in which the Federal Government has declined to intervene; the relator in a nonintervened suit is not “the official of the United States” whose knowledge triggers §3731(b)(2)’s limitations period.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"23"}},{"t":"case","label":"Corcoran v. CVS Health Corp.","cite":"779 F. App’x 431","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/779/431/","by":{"3":"6"}},{"t":"case","label":"McFadden v. United States","cite":"576 U.S. 186","y":2015,"id":"2014/14-378","sc":1,"sum":"The Court decided that in order to fulfill the intent element of The Controlled Substance Analogue Enforcement Act of 1986, a person must either know that the substance is a controlled substance or be aware of what the substance is without knowing that it is controlled.","sumSrc":"Oyez","by":{"3":"25"}},{"t":"case","label":"Muscarello v. United States","cite":"524 U.S. 125","y":1998,"id":"1997/96-1654","sc":1,"sum":"The Court held that the phrase \"carries a firearm\" applies to a person who knowingly possesses and conveys firearms in a vehicle, including in the locked glove compartment or trunk of a car, which the person accompanies.","sumSrc":"Oyez","by":{"3":"23"}},{"t":"case","label":"Ocasio v. United States","cite":"578 U.S. 282","y":2016,"id":"2015/14-361","sc":1,"sum":"The Court determined that a conspiracy to commit extortion can involve the purported victims of the extortion as members of the conspiracy.","sumSrc":"Oyez","by":{"3":"23"}},{"t":"case","label":"Posters ’N’ Things, Ltd. v. United States","cite":"511 U.S. 513","y":1994,"id":"1993/92-903","sc":1,"op":1,"sum":"Upon searching petitioner Acty's residence and the premises of her business, petitioner Posters 'N' Things, Ltd., officers seized, among other things, pipes, \"bongs,\" scales, \"roach clips,\" drug diluents, and advertisements describing various drug-related products sold by petitioners. Petitioners were indicted on, and convicted in the District Court of, a number of charges, including the use of an interstate …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"25"}},{"t":"case","label":"Rivers v. Roadway Exp., Inc.","cite":"511 U.S. 298","y":1994,"id":"1993/92-938","sc":1,"op":1,"sum":"Section 101 does not apply to a case that arose before it was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"22"}},{"t":"case","label":"Unicolors, Inc. v. H&M Hennes & Mauritz, L.P.","cite":"142 S. Ct. 941","y":2022,"id":"2021/20-915","sc":1,"ar":1,"sum":"Lack of either factual or legal knowledge can excuse an inaccuracy in a copyright registration under 17 U. S. C. §411(b)(1)(A)’s safe harbor.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"22"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"3":"24"}}]};